// Placeholder content for protocols not fully written
function placeholder(name: string, layer: string, tcpLayer: string, ports: string): ProtocolContent {
  return {
    title: name,
    whatItIs: `${name} is a networking protocol. Detailed content coming soon. This protocol plays an important role in modern network communications.`,
    osiLayer: layer,
    tcpIpLayer: tcpLayer,
    ports: ports,
    realLife: 'Detailed real-world examples coming soon.',
    securityRisks: 'Security considerations for this protocol are being documented.',
    wiresharkFilter: name.toLowerCase().replace(/[^a-z]/g, ''),
    wiresharkTip: 'Filter details coming soon.',
    commands: [{ command: `# ${name} commands coming soon`, explanation: 'Detailed command examples are being prepared.' }],
    keyTakeaways: [`${name} is an important protocol to understand`, 'More details will be added soon'],
    quiz: [
      { question: `${name} is a networking protocol.`, type: 'true-false', options: ['True', 'False'], correctAnswer: 'True' },
      { question: `Which layer does ${name} operate at?`, type: 'multiple-choice', options: [layer, 'Layer 1', 'Layer 2', 'Layer 6'], correctAnswer: layer },
      { question: `${name} uses encryption by default.`, type: 'true-false', options: ['True', 'False'], correctAnswer: 'False' },
      { question: `What are the typical ports for ${name}?`, type: 'multiple-choice', options: [ports, 'TCP 80', 'UDP 53', 'TCP 22'], correctAnswer: ports },
      { question: `Understanding ${name} is important for network security.`, type: 'true-false', options: ['True', 'False'], correctAnswer: 'True' },
    ],
  };
}

